    if ($owner!==false && !$traverseOnly && $dedicatedAppDirectory)
        return ['sudo chown -- '.shellArg((string)$uid).' '.$quoted,'sudo chmod u+rwx -- '.$quoted];
    return [];
}
function directoryAdvice(string $path,bool $traverseOnly=false): array {
