    if (!preg_match('/\A(-?\d+)\s*([KMG]?)\z/iD',$value,$m)) return 0;
    return (int)((int)$m[1]*match(strtoupper($m[2])){'K'=>1024,'M'=>1048576,'G'=>1073741824,default=>1});
